import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    with io.StringIO(raw_csv, newline="") as stream:
        records = list(csv.reader(stream, delimiter=",", quotechar='"', doublequote=True))

    first = next(
        (i for i, row in enumerate(records) if any(value.strip() for value in row)),
        None,
    )
    if first is None:
        return {"columns": [], "rows": []}

    expected_width = 10
    header_index = first
    if len(records[first]) != expected_width:
        for i in range(first + 1, len(records)):
            row = records[i]
            if len(row) != expected_width:
                continue
            names = [value.strip() for value in row]
            if len(set(names)) == expected_width and all(
                re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) for name in names
            ):
                header_index = i
                break

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(len(columns), expected_width, max(map(len, rows), default=0))

    used_names = set(columns)
    number = 1
    while len(columns) < width:
        name = f"extra_{number}"
        number += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
